mapper.sql:
WHERE 1=1

  AND (UPPER(NVL(T1.GATE_ID,'')) LIKE '%'||UPPER(#{keyword})||'%'
    OR UPPER(NVL(T1.NAME_KO,'')) LIKE '%'||UPPER(#{keyword})||'%')

AND T1.ACTIVE_YN = #{activeYn}
AND T1.GATE_ID = #{gateId}

mapper.select:
SELECT * FROM (
  SELECT a.*, ROWNUM rnum FROM (
    SELECT T1.GATE_ID AS GATE_ID, T1.NAME_KO AS NAME_KO, T1.DESCRIPTION AS DESCRIPTION,
           T1.SORT_NO AS SORT_NO, T1.ACTIVE_YN AS ACTIVE_YN
      FROM TB_IF_GATE_DEF_PILOT T1

     ORDER BY T1.SORT_NO, T1.GATE_ID
  ) a WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rnum > #{offset}

SELECT GATE_ID AS GATE_ID, NAME_KO AS NAME_KO, DESCRIPTION AS DESCRIPTION,
       SORT_NO AS SORT_NO, ACTIVE_YN AS ACTIVE_YN
  FROM TB_IF_GATE_DEF_PILOT WHERE GATE_ID = #{gateId}

mapper.update:
UPDATE TB_IF_GATE_DEF_PILOT SET
  NAME_KO=#{nameKo}, DESCRIPTION=#{description}, SORT_NO=#{sortNo}, ACTIVE_YN=#{activeYn}
 WHERE GATE_ID=#{gateId}
